#### Authorization Code Flow with PKCE

Implementation requirements for user authentication:

```javascript
// PKCE Implementation Example
import { randomBytes, createHash } from 'crypto';

class PKCEAuthenticator {
    constructor(clientId, redirectUri, idpUrl) {
        this.clientId = clientId;
        this.redirectUri = redirectUri;
        this.idpUrl = idpUrl;
    }

    generatePKCE() {
        const codeVerifier = randomBytes(32).toString('base64url');
        const codeChallenge = createHash('sha256').update(codeVerifier).digest('base64url');

        return {
            codeVerifier,
            codeChallenge,
            codeChallengeMethod: 'S256',
        };
    }

    buildAuthUrl(scopes = ['openid', 'profile', 'email']) {
        const { codeChallenge, codeChallengeMethod } = this.generatePKCE();
        const state = randomBytes(16).toString('hex');

        const params = new URLSearchParams({
            response_type: 'code',
            client_id: this.clientId,
            redirect_uri: this.redirectUri,
            scope: scopes.join(' '),
            state: state,
            code_challenge: codeChallenge,
            code_challenge_method: codeChallengeMethod,
        });

        return `${this.idpUrl}/oauth2/authorize?${params}`;
    }
}
```

