#### Federation Support

```python
# SAML 2.0 Federation Example
from onelogin.saml2.auth import OneLogin_Saml2_Auth
from onelogin.saml2.settings import OneLogin_Saml2_Settings

class SAMLFederationHandler:
    def __init__(self, saml_settings: dict):
        self.settings = OneLogin_Saml2_Settings(saml_settings)

    def initiate_sso(self, request, relay_state: str = None):
        auth = OneLogin_Saml2_Auth(request, self.settings)
        return auth.login(return_to=relay_state)

    def process_sso_response(self, request):
        auth = OneLogin_Saml2_Auth(request, self.settings)
        auth.process_response()

        if auth.is_authenticated():
            return {
                "user_id": auth.get_nameid(),
                "attributes": auth.get_attributes(),
                "session_index": auth.get_session_index()
            }
        else:
            raise AuthenticationError(auth.get_errors())
